"use strict";

// Scores and renders the issue-intake replay (spec 010 D12) from the rows
// jev-intake-replay.cjs evaluates. Pure: no file, network or gh access.

const { THRESHOLDS } = require("./jev-issue-intake.cjs");

function score(rows) {
  const routed = rows.filter((row) => row.truthAreas);
  const areaRight = routed.filter((row) => row.truthAreas.includes(row.area));
  const areaNone = routed.filter((row) => row.area === null);
  const picks = (verb) => rows.filter((row) => row.outcome.startsWith(verb));
  const right = (list) => list.filter((row) => row.outcome === row.expected).length;
  const wrong = (list) =>
    list.filter((row) => row.outcome !== row.expected && !row.merged).map((row) => row.number);
  const closes = picks("close");
  const comments = picks("comment");
  return {
    issues: rows.length,
    routed: routed.length,
    areaRight: areaRight.length,
    areaWrong: routed.length - areaRight.length - areaNone.length,
    areaNone: areaNone.length,
    closes: closes.map((row) => `#${row.number} ${row.outcome} (${row.evidence})`),
    wrongAreas: routed
      .filter((row) => row.area !== null && !row.truthAreas.includes(row.area))
      .map((row) => `#${row.number} ${row.area} (board ${row.truthAreas.join(", ")})`),
    rightCloses: right(closes),
    wrongCloses: wrong(closes),
    rightComments: right(comments),
    wrongComments: wrong(comments),
    merged: rows.filter((row) => row.merged).map((row) => `#${row.number} ${row.outcome}`),
    missed: rows
      .filter((row) => row.expected !== "none" && row.outcome !== row.expected)
      .map((row) => row.number),
  };
}

function render({ corpus, rows, model, command }) {
  const head = `# Issue-intake replay

Generated by \`node .github/scripts/jev-intake-replay.cjs report\` (row 010-30, spec 010 D12). Corpus fetched ${corpus.fetchedAt} from ${corpus.repo}: ${corpus.issues.length} issues.

Truth is the board, not a model: the area of each issue routed by a \`gh-N to NNN-MM\` line, mapped through D12's area list, and the duplicate verdicts gh-30 of #6, gh-29 of #5 and #16 of #3 (row 004-65). Every other issue is a non-duplicate, except that a pick of an issue the board routed to the same row is counted apart: the human merged those without calling them duplicates. Type labels have no human truth and are listed, not scored. Outcomes are the applicator's with \`ISSUE_INTAKE_CLOSE_DUPLICATES\` on: \`close #N\` for a duplicate of an open candidate, \`comment #N\` for one of a closed candidate. Thresholds: ${Object.entries(
    THRESHOLDS,
  )
    .map(([key, value]) => `\`${key}\` ${value}`)
    .join(", ")}.
`;
  if (rows.length === 0) {
    return `${head}
## Result

Pending: no Jev answers are recorded, since \`TYPESAFE_API_KEY\` was not available. Run:

\`\`\`sh
${command}
\`\`\`
`;
  }
  const s = score(rows);
  const list = (numbers) => (numbers.length ? numbers.map((n) => `#${n}`).join(", ") : "none");
  const items = (lines) => (lines.length ? lines.join("; ") : "none");
  const table = rows.map(
    (row) =>
      `| #${row.number} | ${row.truthAreas ? row.truthAreas.join(", ") : "–"} | ${row.area ?? "none"} | ${row.type ?? "none"} | ${row.expected} | ${row.outcome} |`,
  );
  return `${head}Model: ${model}.

## Result

- Areas: ${s.areaRight} of ${s.routed} routed issues right, ${s.areaWrong} wrong, ${s.areaNone} without an area.
- Wrong areas against the board: ${items(s.wrongAreas)}.
- Every close it would make: ${items(s.closes)}.
- Closes: ${s.rightCloses} right; wrong closes: ${list(s.wrongCloses)}.
- "Possibly the same" comments: ${s.rightComments} right; wrong: ${list(s.wrongComments)}.
- Picks of an issue merged into the same row, left out of the counts above: ${items(s.merged)}.
- Board duplicates Jev missed: ${list(s.missed)}.

| Issue | Board area | Jev area | Jev type | Board outcome | Jev outcome |
| --- | --- | --- | --- | --- | --- |
${table.join("\n")}
`;
}

module.exports = { score, render };
